window.AUTH=window.AUTH||{};window.AUTH["23-1345"]={"d":"23-1345","id":"2024/23-1345","n":"Rivers v. Guerrero","briefs":[{"k":"petitioner","label":"Brief of petitioner Danny Richard Rivers","date":"2025-01-21","url":"https://www.supremecourt.gov/DocketPDF/23/23-1345/339797/20250121162402544_23-1345%20Brief%20for%20Petitioner_A.pdf","side":"pet","n":120},{"k":"respondent","label":"Brief of respondent Eric Guerrero, Director, Texas Department of Criminal Justice, Correctional Institutions Division","date":"2025-02-20","url":"https://www.supremecourt.gov/DocketPDF/23/23-1345/344259/20250220152625809_23-1345%20Brief%20for%20Respondent.pdf","side":"res","n":75},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2025-02-27","url":"https://www.supremecourt.gov/DocketPDF/23/23-1345/350864/20250227152906559_23-1345bsacUnitedStates.pdf","side":"us","n":65},{"k":"reply","label":"Reply of petitioner Danny Richard Rivers","date":"2025-03-20","url":"https://www.supremecourt.gov/DocketPDF/23/23-1345/352586/20250320134219631_Rivers%20-%20Reply%20Final.pdf","side":"pet","n":66}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us2r46_kjfm.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Am. Hosp. Ass’n v. Becerra","cite":"596 U.S. 724","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/724/","sc":1,"by":{"0":"43"}},{"t":"case","label":"Andrews v. Deland","cite":"943 F.2d 1162","y":1991,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/943/1162/","by":{"0":"39"}},{"t":"case","label":"Andrus v. Texas","cite":"590 U.S. 806","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/806/","sc":1,"op":8,"by":{"0":"35"}},{"t":"case","label":"Artuz v. Bennett","cite":"531 U.S. 4","y":2000,"id":"2000/99-1238","sc":1,"sum":"The Court held that an application for state postconviction relief containing procedurally barred claims is properly filed within the meaning of the Antiterrorism and Effective Death Penalty Act of 1996.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Ballard v. Searls","cite":"130 U.S. 50","y":1889,"id":"scdb/1888-147","sc":1,"sum":"Searls, tbe appellee, filed a bill in tbe Circuit Court of the United States for the Eastern District of Michigan against Worden for infringement of letters patent.. After hearing, a decree was entered in that case in his favor for the recovery of $24,960.31 damages and costs. Worden appealed. to this court, but gave no supersedeas bond. Thereupon execution issued on the decree, which was levied on certain lots, the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Banister v. Davis","cite":"590 U.S. 504","y":2020,"id":"2019/18-6943","sc":1,"op":12,"ar":13,"sum":"The Court held that a timely Rule 59(e) motion to “amend or alter” a habeas court’s judgment is not a second or successive habeas petition.","sumSrc":"Oyez","by":{"0":"2, 3, 4, 5, 25, 27, 28","1":"1, 12-14, 18-20, 22, 24-29, 35, 37","2":"2, 10, 12, 16, 18, 21, 22, 24","3":"1, 7, 9, 18"}},{"t":"case","label":"Bennett v. Robbins","cite":"329 F.2d 146","y":1964,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/329/146/","by":{"0":"30","1":"36"}},{"t":"case","label":"Bishop v. Lane","cite":"478 F. Supp. 865","y":1978,"court":"E.D. Tenn.","url":"https://www.courtlistener.com/c/F.%20Supp./478/865/","by":{"0":"30"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"sum":"The Court held that the Military Commissions Act of 2006 violated the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Boyd v. Sec’y, Dep’t of Corr.","cite":"114 F.4th 1232","y":2024,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/114/1232/","by":{"0":"35","1":"28"}},{"t":"case","label":"Briddle v. Scott","cite":"63 F.3d 364","y":1995,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/63/364/","by":{"0":"30"}},{"t":"case","label":"Brown v. Davenport","cite":"142 S. Ct. 1510","y":2022,"id":"2021/20-826","sc":1,"sum":"When a state court has ruled on the merits of a state prisoner’s claim, a federal court cannot grant habeas relief without applying both the test this Court outlined in Brecht v. Abrahamson, 507 U. S. 619, and the one Congress prescribed in the Antiterrorism and Effective Death Penalty Act of 1996; the Sixth Circuit erred in granting habeas relief to Mr. Davenport based solely on its assessment that he could satisfy the Brecht standard.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"41"}},{"t":"case","label":"Brown v. United States","cite":"384 F. App’x 815","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/384/815/","by":{"0":"33"}},{"t":"case","label":"Calderon v. Ashmus","cite":"523 U.S. 740","y":1998,"id":"1997/97-391","sc":1,"sum":"The Court held that \"this action for a declaratory judgment and injunctive relief is not a justiciable case within the meaning of Article III.\" \"If the class members file habeas petitions, and the State asserts Chapter 154, the members obviously can litigate California's compliance with Chapter 154 at that time.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Ca. ex rel. Cooper v. Mitchell Bros.’ Santa Ana Theater","cite":"454 U.S. 90","y":1981,"id":"1981/81-271","sc":1,"sum":"A city, in a public nuisance abatement action against a motion picture theater, is not required, as a matter of constitutional law, to establish the obscenity of the motion pictures at issue by proof \"beyond a reasonable doubt.\" While a State may require such proof in such a case, that choice is solely a matter of state law and is not required by the First and Fourteenth Amendments. Although this Court has held that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"Carey v. Saffold","cite":"536 U.S. 214","y":2002,"id":"2001/01-301","sc":1,"sum":"The Court held that, as used in AEDPA, \"pending\" covers the time between a lower state court's decision and the filing of a notice of appeal to a higher state court.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Castro v. United States","cite":"540 U.S. 375","y":2003,"id":"2003/02-6683","sc":1,"sum":"The Court held that a federal court can recharacterize a motion as a first habeas corpus petition only if the court: (1) informs the litigant of the court's intent to recharacterize; (2) warns the litigant that this recharacterization means that any subsequent habeas corpus petition will be treated as a second petition; (3) gives the litigant an opportunity to withdraw or amend the motion.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Ching v. United States","cite":"298 F.3d 174","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/298/174/","ar":1,"by":{"0":"44","1":"40","3":"10"}},{"t":"case","label":"Clarke v. Henderson","cite":"403 F.2d 687","y":1968,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/403/687/","by":{"0":"30","1":"36"}},{"t":"case","label":"Clay v. United States","cite":"537 U.S. 522","y":2003,"id":"2002/01-1500","sc":1,"sum":"The Court held that, for the purpose of starting the clock on section 2255's one-year limitation period, a judgment of conviction becomes final when the time expires for filing a petition for certiorari contesting the appellate court's affirmation of the conviction. Under this rule, Clay's section 2255 motion was timely filed.","sumSrc":"Oyez","by":{"0":"38, 40","1":"37, 38","2":"23, 24","3":"15"}},{"t":"case","label":"Cooper v. United States","cite":"2013 WL 57043","y":2013,"court":"S.D.N.Y Jan. 4","by":{"0":"45"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"D.W. Bosley Co. v. Wirfs","cite":"20 F.2d 629","y":1927,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/20/629/","by":{"0":"21","1":"32, 33"}},{"t":"case","label":"Dietz v. Horton Mfg. Co.","cite":"170 F. 865","y":1909,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F./170/865/","by":{"0":"21"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"FCC v. NextWave Personal Commc’ns Inc.","cite":"537 U.S. 293","y":2003,"id":"2002/01-653","sc":1,"sum":"The Court held that the FCC's cancellations of the licenses violated section 525(a) as revocations of government licenses solely for nonpayment of the debtors' dischargeable debts.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Foman v. Davis","cite":"371 U.S. 178","y":1962,"id":"1962/41","sc":1,"sum":"A Federal District Court dismissed petitioner's complaint in a civil action for failure to state a claim upon which relief might be granted. Petitioner promptly moved to vacate the judgment and amend the complaint so as to state an alternative theory for recovery. Before the Court ruled on those motions, petitioner filed notice of appeal from the judgment of dismissal. Subsequently, the District Court denied the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 44"}},{"t":"case","label":"Giles v. Maryland","cite":"386 U.S. 66","y":1967,"id":"1966/27","sc":1,"sum":"The judgment is vacated and the case is remanded to the Maryland Court of Appeals for further proceedings. Pp. 67-102. 239 Md. 458, 212 A. 2d 101, vacated and remanded. MR. JUSTICE BRENNAN, joined by THE CHIEF JUSTICE and MR. JUSTICE DOUGLAS, without reaching the question of the extent of the prosecution's duty of disclosure, concluded that evidence of two police reports which were submitted to this Court but were …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","3":"14"}},{"t":"case","label":"Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"id":"2004/04-6432","sc":1,"op":4,"sum":"Explaining that motions that do not “substantively addres[s] federal grounds for setting aside the movant's state conviction,” for example, are not subject to the second-or-successive bar.","sumSrc":"opinion","by":{"0":"5","2":"2, 8, 9, 12, 17-19, 21","3":"1, 3"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"sum":"The Court held that a prisoner who does not seek review in a state’s highest court faces final judgment for the purposes of Section 2244(d)(1)(A) upon “expiration of the time for seeking such review.”","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"Griggs v. Provident Consumer Disc. Co.","cite":"459 U.S. 56","y":1982,"id":"1982/82-5082","sc":1,"sum":"The Court of Appeals' analysis of Rule 4(a)(4) is contrary to the language and purposes of the 1979 amendments to the Rules of Appellate Procedure. Prior to 1979, if a notice of appeal was fied pending disposition of a motion to vacate, alter, or amend the judgment it was generally held that the district court retained jurisdiction to decide the motion and the notice of appeal was adequate for purposes of beginning …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 45","2":"20"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"by":{"0":"29","1":"36","3":"8"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"90 F. Supp. 431","y":1950,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./90/431/","by":{"0":"28, 29","1":"35","3":"7"}},{"t":"case","label":"Holiday v. Johnston","cite":"313 U.S. 342","y":1941,"id":"scdb/1940-145","sc":1,"sum":"1. The erroneous imposition of two sentences for a single offense of which the accused has been convicted, or as to which he has pleaded guilty, does not constitute double jeopardy.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"J.E.M. Ag Supply, Inc. v. Pioneer Hi-Bred Int’l, Inc.","cite":"534 U.S. 124","y":2001,"id":"2001/99-1996","sc":1,"sum":"The Court held that utility patents may be issued for plants.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"James v. Walsh","cite":"308 F.3d 162","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/308/162/","by":{"0":"44"}},{"t":"case","label":"Kyles v. Whitley","cite":"514 U.S. 419","y":1995,"id":"1994/93-7927","sc":1,"sum":"The Supreme Court held that Kyles was entitled to a new trial because the net effect of the suppressed evidence raised a reasonable probability that the jury would have reached a different result. The Fifth Circuit used the wrong standard and failed to consider the cumulative effect of all the evidence that the prosecution failed to disclose.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Levinson v. United States","cite":"32 F.2d 449","y":1929,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/32/449/","by":{"0":"20"}},{"t":"case","label":"Lewis v. Brown","cite":"2013 WL 2181520","y":2013,"court":"W.D.N.Y. May 20","by":{"0":"45"}},{"t":"case","label":"Mackenzie v. A. Engelhard & Sons Co.","cite":"266 U.S. 131","y":1924,"id":"scdb/1924-031","sc":1,"sum":"1. An appeal is a proceeding in the original cause and the suit is pending until the appeal is disposed of.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"op":1,"ar":1,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"0":"46","1":"19, 20, 34"}},{"t":"case","label":"Me. Cmty. Health Options v. United States","cite":"590 U.S. 296","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/296/","sc":1,"op":8,"by":{"0":"24"}},{"t":"case","label":"Markert v. Swift & Co.","cite":"173 F.2d 517","y":1949,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/173/517/","by":{"0":"21"}},{"t":"case","label":"Mayle v. Felix","cite":"545 U.S. 644","y":2005,"id":"2004/04-563","sc":1,"op":3,"sum":"Explaining that motions that do not “substantively addres[s] federal grounds for setting aside the movant's state conviction,” for example, are not subject to the second-or-successive bar.","sumSrc":"opinion","by":{"0":"17, 44","1":"10, 23","2":"13, 16"}},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"sum":"McCleskey's failure to raise his Massiah claim in his first federal habeas petition constituted abuse of the writ.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","2":"22, 25"}},{"t":"case","label":"Mendia v. Garcia","cite":"874 F.3d 1118","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/1118/","by":{"0":"20","1":"31"}},{"t":"case","label":"Mendoza v. Lumpkin","cite":"81 F.4th 461","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/81/461/","by":{"0":"21, 35","1":"43"}},{"t":"case","label":"Munchinski v. Wilson","cite":"694 F.3d 308","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/694/308/","by":{"0":"32"}},{"t":"case","label":"Munoz v. United States","cite":"451 F. App’x 818","y":2011,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/451/818/","by":{"0":"28"}},{"t":"case","label":"O’Sullivan v. Boerckel","cite":"526 U.S. 838","y":1999,"id":"1998/97-2048","sc":1,"sum":"Delivered by Justice Sandra Day O'Connor, the Court held that in order to satisfy the exhaustion requirement, a state prisoner must present his claims to a state supreme court in a petition for discretionary review when that review is part of the State's ordinary appellate review procedure.","sumSrc":"Oyez","by":{"0":"40","1":"38"}},{"t":"case","label":"Parry v. Kerestes","cite":"2013 WL 6002358","y":2013,"court":"W.D. Pa. Nov. 12","by":{"0":"31"}},{"t":"case","label":"Petty v. McCotter","cite":"779 F.2d 299","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/779/299/","by":{"0":"30","1":"36, 37","2":"26","3":"16"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"0":"37, 38"}},{"t":"case","label":"Posadas v. Nat’l City Bank of N.Y.","cite":"296 U.S. 497","y":1936,"id":"scdb/1935-071","sc":1,"by":{"0":"24"}},{"t":"case","label":"Price v. Johnston","cite":"334 U.S. 266","y":1948,"id":"scdb/1947-084","sc":1,"sum":"1. Under § 262 of the Judicial Code, a circuit court of appeals has power, exercisable in the sound discretion of the court, to issue an order, in the nature of a writ of habeas corpus, commanding that a prisoner be brought before the court for the purpose of arguing his own appeal in a case involving his life or liberty.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 26","3":"6"}},{"t":"case","label":"Radzanower v. Touche Ross & Co.","cite":"426 U.S. 148","y":1976,"id":"1975/75-268","sc":1,"sum":"Venue in a suit against a national banking association charged with violating the Securities Exchange Act of 1934 held to be governed by the venue provision of the National Bank Act, 12 U. S. C. § 94, which provides that an action against a national banking association may be had in any federal district court within the district in which such association may be established, rather than by § 27 of the Securities …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 25"}},{"t":"case","label":"Ransom v. City of Pierre","cite":"101 F. 665","y":1900,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./101/665/","by":{"0":"20"}},{"t":"case","label":"Ret. Bd. of Policemen’s Annuity & Benefit Fund v. Bank of N.Y. Mellon","cite":"297 F.R.D. 218","y":2013,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.R.D./297/218/","by":{"0":"19","1":"16, 32"}},{"t":"case","label":"Richards v. Quarterman","cite":"566 F.3d 553","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/566/553/","by":{"0":"46"}},{"t":"case","label":"Rivers v. Davis","cite":"2018 WL 4443153","y":2018,"court":"N.D. Tex. July 27","by":{"0":"9, 46"}},{"t":"case","label":"Rivers v. Lumpkin","cite":"2022 WL 1517027","y":2022,"court":"5th Cir. May 13","by":{"0":"10, 12","1":"9"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"589 U.S. 8","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Salinger v. Loisel","cite":"265 U.S. 224","y":1924,"id":"scdb/1923-152","sc":1,"sum":"1. Warrants of removal issued in triplicate are in legal effect but a single warrant, and defendant who had secured a supersedeas on appeal from an order refusing relief by habeas corpus from arrest under one, could not lawfully be arrested under another.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"26, 38","1":"39"}},{"t":"case","label":"Sanders v. United States","cite":"373 U.S. 1","y":1963,"id":"1962/202","sc":1,"sum":"The Court should have granted a hearing on the second motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Scarborough v. U.S. Sec. Assocs., Inc.","cite":"836 F. App’x 60","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/836/60/","by":{"0":"20"}},{"t":"case","label":"Steele v. United States","cite":"2022 WL 4292271","y":2022,"court":"S.D.N.Y. Sept. 16","by":{"0":"45"}},{"t":"case","label":"Strand v. United States","cite":"780 F.2d 1497","y":1985,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/780/1497/","ar":1,"by":{"0":"29, 30, 33","1":"36","3":"8"}},{"t":"case","label":"Thomas v. Virginia","cite":"357 F.2d 87","y":1966,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/357/87/","op":2,"by":{"0":"30","1":"36"}},{"t":"case","label":"United States v. Bagley","cite":"473 U.S. 667","y":1985,"id":"1984/84-48","sc":1,"sum":"The Court held that the government’s failure to disclose the contacts in discovery did not violate the Due Process Clause. Justice Blackmun wrote that the state was required by due process to disclose evidence that was both favorable to the accused and material to either guilt or punishment, and that impeachment evidence fell within this requirement.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"United States v. Cronic","cite":"466 U.S. 648","y":1984,"id":"1983/82-660","sc":1,"sum":"The Court held that the Court of Appeals erred by inferring that the less-than-ideal circumstances leading up to the trial negatively influenced the lawyer’s performance. The Sixth Amendment protects the right for an accused to receive effective assistance of counsel in order to protect the adversary process.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"United States ex rel. Harisiades v. Shaughnessy","cite":"187 F.2d 137","y":1951,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/187/137/","by":{"0":"28, 29, 33"}},{"t":"case","label":"United States v. Hayman","cite":"342 U.S. 205","y":1952,"id":"scdb/1951-024","sc":1,"sum":"The District Court erred in determining the factual issues raised by respondent's motion under § 2255 without notice to respondent and without his presence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"United States v. Santarelli","cite":"929 F.3d 95","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/929/95/","op":2,"by":{"0":"37, 44","1":"40","3":"10"}},{"t":"case","label":"United States v. Shotwell Mfg. Co.","cite":"355 U.S. 233","y":1957,"id":"1957/1","sc":1,"ar":1,"sum":"Because Shotwell, et al. were found guilty, there was no double jeopardy issue. The district court was the proper venue for the remand because there were questions about the integrity of the record. Justice Hugo L. Black wrote a dissent, stating that the Court should have denied certiorari and let the case take its regular course back to the district court for a new trial based on the decision by the court of appeals.","sumSrc":"Oyez","by":{"0":"20","3":"14"}},{"t":"case","label":"Waley v. Johnston","cite":"316 U.S. 101","y":1942,"id":"scdb/1941-129","sc":1,"by":{"0":"27"}},{"t":"case","label":"Walker v. Lockhart","cite":"514 F. Supp. 1347","y":1981,"court":"E.D. Ark.","url":"https://www.courtlistener.com/c/F.%20Supp./514/1347/","by":{"0":"38, 39","1":"40"}},{"t":"case","label":"Watts, Watts & Co. v. Unione Austriaca Di Navigazione","cite":"248 U.S. 9","y":1918,"id":"scdb/1918-034","sc":1,"sum":"(1) That the libelant as a co-belligerent had a right to maintain the suit against the respondent, an 'alien enemy, and that jurisdiction should not be declined as an act of discretion. P. 21..","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20, 21"}},{"t":"case","label":"Whitney v. United States","cite":"424 F. Supp. 1236","y":1976,"court":"E.D. Mo.","url":"https://www.courtlistener.com/c/F.%20Supp./424/1236/","by":{"0":"39"}},{"t":"case","label":"Whab v. United States","cite":"408 F.3d 116","y":2005,"court":"2d. Cir.","url":"https://www.courtlistener.com/c/F.3d/408/116/","op":1,"by":{"0":"37, 45","1":"40"}},{"t":"case","label":"Wong Doo v. United States","cite":"265 U.S. 239","y":1924,"id":"scdb/1923-153","sc":1,"sum":"1. Thg strict -doctrine of res judieoato does not apply to habeascorpus. Salinger v. Loisel, cte, 224.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 2106","url":"https://www.law.cornell.edu/uscode/text/28/2106","stext":{"head":"§2106. Determination","paras":[[0,"The Supreme Court or any other court of appellate jurisdiction may affirm, modify, vacate, set aside or reverse any judgment, decree, or order of a court lawfully brought before it for review, and may remand the cause and direct the entry of such appropriate judgment, decree, or order, or require such further proceedings to be had as may be just under the circumstances."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2106?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2106. Determination","tname":"Judiciary and Judicial Procedure","by":{"0":"1, 13, 20","2":"11, 29, 30"}},{"t":"usc","label":"28 U.S.C. § 2242","url":"https://www.law.cornell.edu/uscode/text/28/2242","subs":["(1952)"],"stext":{"head":"§2242. Application","paras":[[0,"Application for a writ of habeas corpus shall be in writing signed and verified by the person for whose relief it is intended or by someone acting in his behalf."],[0,"It shall allege the facts concerning the applicant's commitment or detention, the name of the person who has custody over him and by virtue of what claim or authority, if known."],[0,"It may be amended or supplemented as provided in the rules of procedure applicable to civil actions."],[0,"If addressed to the Supreme Court, a justice thereof or a circuit judge it shall state the reasons for not making application to the district court of the district in which the applicant is held."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2242?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2242. Application","tname":"Judiciary and Judicial Procedure","by":{"0":"6, 16, 17, 18, 22, 23, 43, 17","2":"9, 13, 16","3":"6, 6"}},{"t":"usc","label":"28 U.S.C. § 2243","url":"https://www.law.cornell.edu/uscode/text/28/2243","by":{"0":"24"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(b)(2)","(b)(2)(B)(i)","(b)(2)(B)(ii)","(b)(3)","(b)(3)(A)","(b)(3)(B)","(b)(4)","(d)(1)(A)","(d)(2)","(b)","(b)(1)","(b)(2)(A)","(b)(3)(C)"],"stext":{"head":"§2244. Finality of determination","paras":[[0,"(a) No circuit or district judge shall be required to entertain an application for a writ of habeas corpus to inquire into the detention of a person pursuant to a judgment of a court of the United States if it appears that the legality of such detention has been determined by a judge or court of the United States on a prior application for a writ of habeas corpus, except as provided in section 2255."],[0,"(b)(1) A claim presented in a second or successive habeas corpus application under section 2254 that was presented in a prior application shall be dismissed."],[0,"(2) A claim presented in a second or successive habeas corpus application under section 2254 that was not presented in a prior application shall be dismissed unless—"],[1,"(A) the applicant shows that the claim relies on a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[1,"(B)(i) the factual predicate for the claim could not have been discovered previously through the exercise of due diligence; and"],[1,"(ii) the facts underlying the claim, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that, but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(3)(A) Before a second or successive application permitted by this section is filed in the district court, the applicant shall move in the appropriate court of appeals for an order authorizing the district court to consider the application."],[0,"(B) A motion in the court of appeals for an order authorizing the district court to consider a second or successive application shall be determined by a three-judge panel of the court of appeals."],[0,"(C) The court of appeals may authorize the filing of a second or successive application only if it determines that the application makes a prima facie showing that the application satisfies the requirements of this subsection."],[0,"(D) The court of appeals shall grant or deny the authorization to file a second or successive application not later than 30 days after the filing of the motion."],[0,"(E) The grant or denial of an authorization by a court of appeals to file a second or successive application shall not be appealable and shall not be the subject of a petition for rehearing or for a writ of certiorari."],[0,"(4) A district court shall dismiss any claim presented in a second or successive application that the court of appeals has authorized to be filed unless the applicant shows that the claim satisfies the requirements of this section."],[0,"(c) In a habeas corpus proceeding brought in behalf of a person in custody pursuant to the judgment of a State court, a prior judgment of the Supreme Court of the United States on an appeal or review by a writ of certiorari at the instance of the prisoner of the decision of such State court, shall be conclusive as to all issues of fact or law with respect to an asserted denial of a Federal right which constitutes ground for discharge in a habeas corpus proceeding, actually adjudicated by the Supreme Court therein, unless the applicant for the writ of habeas corpus shall plead and the court shall find the existence of a material and controlling fact which did not appear in the record of the proceeding in the Supreme Court and the court shall further find that the applicant for the writ of habeas corpus could not have caused such fact to appear in such record by the exercise of reasonable diligence."],[0,"(d)(1) A 1-year period of limitation shall apply to an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court. The limitation period shall run from the latest of—"],[1,"(A) the date on which the judgment became final by the conclusion of direct review or the expiration of the time for seeking such review;"],[1,"(B) the date on which the impediment to filing an application created by State action in violation of the Constitution or laws of the United States is removed, if the applicant was prevented from filing by such State action;"],[1,"(C) the date on which the constitutional right asserted was initially recognized by the Supreme Court, if the right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(D) the date on which the factual predicate of the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(2) The time during which a properly filed application for State post-conviction or other collateral review with respect to the pertinent judgment or claim is pending shall not be counted toward any period of limitation under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2244?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2244. Finality of determination","tname":"Judiciary and Judicial Procedure","by":{"0":"1, 2, 3, 4, 40, 32, 32, 44, 4, 33, 4, 40, 40","2":"12, 30, 1, 2, 5, 6, 9, 16, 17, 19, 20, 22, 24, 5, 5, 6, 6, 5, 5, 5, 24","3":"6"}},{"t":"usc","label":"28 U.S.C. § 2253","url":"https://www.law.cornell.edu/uscode/text/28/2253","subs":["(c)(1)","(c)"],"stext":{"head":"§2253. Appeal","paras":[[0,"(a) In a habeas corpus proceeding or a proceeding under section 2255 before a district judge, the final order shall be subject to review, on appeal, by the court of appeals for the circuit in which the proceeding is held."],[0,"(b) There shall be no right of appeal from a final order in a proceeding to test the validity of a warrant to remove to another district or place for commitment or trial a person charged with a criminal offense against the United States, or to test the validity of such person's detention pending removal proceedings."],[0,"(c)(1) Unless a circuit justice or judge issues a certificate of appealability, an appeal may not be taken to the court of appeals from—"],[1,"(A) the final order in a habeas corpus proceeding in which the detention complained of arises out of process issued by a State court; or"],[1,"(B) the final order in a proceeding under section 2255."],[0,"(2) A certificate of appealability may issue under paragraph (1) only if the applicant has made a substantial showing of the denial of a constitutional right."],[0,"(3) The certificate of appealability under paragraph (1) shall indicate which specific issue or issues satisfy the showing required by paragraph (2)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2253?type=usc&year=mostrecent&link-type=html"},"head":"§2253. Appeal","tname":"Judiciary and Judicial Procedure","by":{"0":"33","2":"4, 23","3":"18"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(b)(1)(A)","(c)","(d)","(a)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"op":12,"ar":1,"head":"§2254. State custody; remedies in Federal courts","tname":"Judiciary and Judicial Procedure","by":{"0":"5, 40","2":"1, 4, 5, 7, 14, 4, 4, 4","3":"3"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(f)(1)","(h)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"0":"40","2":"1, 1"}},{"t":"usc","label":"28 U.S.C. § 2261","url":"https://www.law.cornell.edu/uscode/text/28/2261","stext":{"head":"§2261. Prisoners in State custody subject to capital sentence; appointment of counsel; requirement of rule of court or statute; procedures for appointment","paras":[[0,"(a) This chapter shall apply to cases arising under section 2254 brought by prisoners in State custody who are subject to a capital sentence. It shall apply only if the provisions of subsections (b) and (c) are satisfied."],[0,"(b) Counsel.—This chapter is applicable if—"],[1,"(1) the Attorney General of the United States certifies that a State has established a mechanism for providing counsel in postconviction proceedings as provided in section 2265; and"],[1,"(2) counsel was appointed pursuant to that mechanism, petitioner validly waived counsel, petitioner retained counsel, or petitioner was found not to be indigent."],[0,"(c) Any mechanism for the appointment, compensation, and reimbursement of counsel as provided in subsection (b) must offer counsel to all State prisoners under capital sentence and must provide for the entry of an order by a court of record—"],[1,"(1) appointing one or more counsels to represent the prisoner upon a finding that the prisoner is indigent and accepted the offer or is unable competently to decide whether to accept or reject the offer;"],[1,"(2) finding, after a hearing if necessary, that the prisoner rejected the offer of counsel and made the decision with an understanding of its legal consequences; or"],[1,"(3) denying the appointment of counsel upon a finding that the prisoner is not indigent."],[0,"(d) No counsel appointed pursuant to subsections (b) and (c) to represent a State prisoner under capital sentence shall have previously represented the prisoner at trial in the case for which the appointment is made unless the prisoner and counsel expressly request continued representation."],[0,"(e) The ineffectiveness or incompetence of counsel during State or Federal post-conviction proceedings in a capital case shall not be a ground for relief in a proceeding arising under section 2254. This limitation shall not preclude the appointment of different counsel, on the court's own motion or at the request of the prisoner, at any phase of State or Federal post-conviction proceedings on the basis of the ineffectiveness or incompetence of counsel in such proceedings."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2261?type=usc&year=mostrecent&link-type=html"},"head":"§2261. Prisoners in State custody subject to capital sentence; appointment of counsel; requirement of rule of court or statute; procedures for appointment","tname":"Judiciary and Judicial Procedure","by":{"0":"23","2":"17"}},{"t":"usc","label":"28 U.S.C. § 2263","url":"https://www.law.cornell.edu/uscode/text/28/2263","subs":["(a)","(b)(2)"],"by":{"0":"40, 40"}},{"t":"usc","label":"28 U.S.C. § 2266","url":"https://www.law.cornell.edu/uscode/text/28/2266","subs":["(b)(2)","(b)(3)(B)","(b)(2)(B)"],"stext":{"head":"§2266. Limitation periods for determining applications and motions","paras":[[0,"(a) The adjudication of any application under section 2254 that is subject to this chapter, and the adjudication of any motion under section 2255 by a person under sentence of death, shall be given priority by the district court and by the court of appeals over all noncapital matters."],[0,"(b)(1)(A) A district court shall render a final determination and enter a final judgment on any application for a writ of habeas corpus brought under this chapter in a capital case not later than 450 days after the date on which the application is filed, or 60 days after the date on which the case is submitted for decision, whichever is earlier."],[0,"(B) A district court shall afford the parties at least 120 days in which to complete all actions, including the preparation of all pleadings and briefs, and if necessary, a hearing, prior to the submission of the case for decision."],[0,"(C)(i) A district court may delay for not more than one additional 30-day period beyond the period specified in subparagraph (A), the rendering of a determination of an application for a writ of habeas corpus if the court issues a written order making a finding, and stating the reasons for the finding, that the ends of justice that would be served by allowing the delay outweigh the best interests of the public and the applicant in a speedy disposition of the application."],[0,"(ii) The factors, among others, that a court shall consider in determining whether a delay in the disposition of an application is warranted are as follows:"],[1,"(I) Whether the failure to allow the delay would be likely to result in a miscarriage of justice."],[1,"(II) Whether the case is so unusual or so complex, due to the number of defendants, the nature of the prosecution, or the existence of novel questions of fact or law, that it is unreasonable to expect adequate briefing within the time limitations established by subparagraph (A)."],[1,"(III) Whether the failure to allow a delay in a case that, taken as a whole, is not so unusual or so complex as described in subclause (II), but would otherwise deny the applicant reasonable time to obtain counsel, would unreasonably deny the applicant or the government continuity of counsel, or would deny counsel for the applicant or the government the reasonable time necessary for effective preparation, taking into account the exercise of due diligence."],[0,"(iii) No delay in disposition shall be permissible because of general congestion of the court's calendar."],[0,"(iv) The court shall transmit a copy of any order issued under clause (i) to the Director of the Administrative Office of the United States Courts for inclusion in the report under paragraph (5)."],[0,"(2) The time limitations under paragraph (1) shall apply to—"],[1,"(A) an initial application for a writ of habeas corpus;"],[1,"(B) any second or successive application for a writ of habeas corpus; and"],[1,"(C) any redetermination of an application for a writ of habeas corpus following a remand by the court of appeals or the Supreme Court for further proceedings, in which case the limitation period shall run from the date the remand is ordered."],[0,"(3)(A) The time limitations under this section shall not be construed to entitle an applicant to a stay of execution, to which the applicant would otherwise not be entitled, for the purpose of litigating any application or appeal."],[0,"(B) No amendment to an application for a writ of habeas corpus under this chapter shall be permitted after the filing of the answer to the application, except on the grounds specified in section 2244(b)."],[0,"(4)(A) The failure of a court to meet or comply with a time limitation under this section shall not be a ground for granting relief from a judgment of conviction or sentence."],[0,"(B) The State may enforce a time limitation under this section by petitioning for a writ of mandamus to the court of appeals. The court of appeals shall act on the petition for a writ of mandamus not later than 30 days after the filing of the petition."],[0,"(5)(A) The Administrative Office of the United States Courts shall submit to Congress an annual report on the compliance by the district courts with the time limitations under this section."],[0,"(B) The report described in subparagraph (A) shall include copies of the orders submitted by the district courts under paragraph (1)(B)(iv)."],[0,"(c)(1)(A) A court of appeals shall hear and render a final determination of any appeal of an order granting or denying, in whole or in part, an application brought under this chapter in a capital case not later than 120 days after the date on which the reply brief is filed, or if no reply brief is filed, not later than 120 days after the date on which the answering brief is filed."],[0,"(B)(i) A court of appeals shall decide whether to grant a petition for rehearing or other request for rehearing en banc not later than 30 days after the date on which the petition for rehearing is filed unless a responsive pleading is required, in which case the court shall decide whether to grant the petition not later than 30 days after the date on which the responsive pleading is filed."],[0,"(ii) If a petition for rehearing or rehearing en banc is granted, the court of appeals shall hear and render a final determination of the appeal not later than 120 days after the date on which the order granting rehearing or rehearing en banc is entered."],[0,"(2) The time limitations under paragraph (1) shall apply to—"],[1,"(A) an initial application for a writ of habeas corpus;"],[1,"(B) any second or successive application for a writ of habeas corpus; and"],[1,"(C) any redetermination of an application for a writ of habeas corpus or related appeal following a remand by the court of appeals en banc or the Supreme Court for further proceedings, in which case the limitation period shall run from the date the remand is ordered."],[0,"(3) The time limitations under this section shall not be construed to entitle an applicant to a stay of execution, to which the applicant would otherwise not be entitled, for the purpose of litigating any application or appeal."],[0,"(4)(A) The failure of a court to meet or comply with a time limitation under this section shall not be a ground for granting relief from a judgment of conviction or sentence."],[0,"(B) The State may enforce a time limitation under this section by applying for a writ of mandamus to the Supreme Court."],[0,"(5) The Administrative Office of the United States Courts shall submit to Congress an annual report on the compliance by the courts of appeals with the time limitations under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2266?type=usc&year=mostrecent&link-type=html"},"head":"§2266. Limitation periods for determining applications and motions","tname":"Judiciary and Judicial Procedure","by":{"0":"23, 14, 23","2":"17","3":"6, 6"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"24","2":"5"}},{"t":"rule","label":"Fed. R. App. P. 12.1","url":"https://www.law.cornell.edu/rules/frap/rule_12.1","subs":["(b)"],"by":{"0":"13, 1, 20","2":"28"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)","(h)"],"by":{"0":"18, 18"}},{"t":"rule","label":"Fed. R. Civ. P. 15","url":"https://www.law.cornell.edu/rules/frcp/rule_15","subs":["(a)(2)","(b)(2)"],"by":{"0":"17, 18"}},{"t":"rule","label":"Fed. R. Civ. P. 59","url":"https://www.law.cornell.edu/rules/frcp/rule_59","subs":["(e)"],"by":{"0":"43"}},{"t":"rule","label":"Fed. R. Civ. P. 62.1","url":"https://www.law.cornell.edu/rules/frcp/rule_62.1","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(c)"],"by":{"0":"19, 20, 19, 19, 19, 21","3":"12, 13"}},{"t":"rule","label":"Fed. R. Civ. P. 81","url":"https://www.law.cornell.edu/rules/frcp/rule_81","subs":["(a)(4)"],"by":{"0":"5"}},{"t":"case","label":"Ahmed v. Dragovich","cite":"297 F.3d 201","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/297/201/","by":{"1":"23","2":"14"}},{"t":"case","label":"Anderson v. Connecticut","cite":"2022 WL 3082985","y":2022,"court":"D. Conn. Aug. 3","ar":1,"by":{"1":"43","3":"19"}},{"t":"case","label":"United States ex rel. Atkins v. McInteer","cite":"470 F.3d 1350","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/470/1350/","by":{"1":"24"}},{"t":"case","label":"Balbuena v. Sullivan","cite":"980 F.3d 619","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/980/619/","op":1,"by":{"1":"24"}},{"t":"case","label":"39, 41 Beaty v. Schriro","cite":"554 F.3d 780","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/554/780/","sum":"Observing that “allow[ing] the filing of new claims this late in the process would essentially nullify the rules about second and successive petitions”.","sumSrc":"brief:2","by":{"1":"43","2":"23"}},{"t":"case","label":"Benson v. St. Joseph Reg’l Health Ctr.","cite":"575 F.3d 542","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/575/542/","by":{"1":"23"}},{"t":"case","label":"Calderon v. Thompson","cite":"523 U.S. 538","y":1998,"id":"1997/97-215","sc":1,"sum":"The Court held that although it was consistent with the Antiterrorism and Effective Death Penalty Act of 1996, the recall was a grave abuse of discretion.","sumSrc":"Oyez","by":{"1":"18","2":"22, 30","3":"12"}},{"t":"case","label":"Camp v. Gregory","cite":"67 F.3d 1286","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/67/1286/","by":{"1":"31"}},{"t":"case","label":"Castro v. United States","cite":"2020 WL 6121220","y":2020,"court":"N.D. Tex. Aug. 24","by":{"1":"28, 29"}},{"t":"case","label":"Ciralsky v. CIA","cite":"355 F.3d 661","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/355/661/","by":{"1":"24"}},{"t":"case","label":"City & County of San Francisco v. Sheehan","cite":"575 U.S. 600","y":2015,"id":"2014/13-1412","sc":1,"sum":"The Court held that an unwarranted entry does not violate the Fourth Amendment when it does not violate a clearly established constitutional or statutory right and is reasonable under the circumstances.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Doucette v. Dep’t of Interior","cite":"849 F.App’x 653","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.App%E2%80%99x/849/653/","by":{"1":"41"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Edwards v. Vannoy","cite":"593 U.S. 255","y":2021,"id":"2020/19-5807","sc":1,"ar":1,"sum":"The jury-unanimity rule announced in Ramos v. Louisiana, 590 U. S. ___, does not apply retroactively on federal collateral review.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21","3":"15"}},{"t":"case","label":"Est. of Najera-Aguirre v. County of Riverside","cite":"2020 WL 5370618","y":2020,"court":"C.D. Cal. Aug. 13","by":{"1":"30"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"op":1,"sum":"The unanimous Court held that the Act's creation of an appellate panel, charged with reviewing all second or successive habeas applications, is not unconstitutional. The Act simply transfers the duty of habeas review from the district courts to an appellate panel.","sumSrc":"Oyez","by":{"1":"19, 38","2":"22"}},{"t":"case","label":"Fisher v. Kadant, Inc.","cite":"589 F.3d 505","y":2009,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/589/505/","by":{"1":"23, 24"}},{"t":"case","label":"(ctd.): Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"url":"https://supreme.justia.com/cases/federal/us/545/524/","sc":1,"op":4,"sum":"Explaining that motions that do not “substantively addres[s] federal grounds for setting aside the movant's state conviction,” for example, are not subject to the second-or-successive bar.","sumSrc":"opinion","by":{"1":"1, 10, 12-14, 19-22, 24-25, 29, 37"}},{"t":"case","label":"41, 46 Haaland v. Brackeen","cite":"599 U.S. 255","y":2023,"id":"2022/21-376","sc":1,"sum":"In child custody proceedings governed by the Indian Child Welfare Act, the Court affirms the Fifth Circuit’s conclusion that ICWA is consistent with Congress’s Article I authority, rejects petitioners’ anticommandeering challenges under the Tenth Amendment, and finds the parties lack standing to litigate their other challenges to ICWA’s placement preferences.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Harington v. Richter","cite":"562 U.S. 86","y":2011,"id":"2010/09-587","sc":1,"sum":"The Court held that a defense lawyer was not deficient for failing to consult blood evidence when planning strategy for trial.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Irvine v. California","cite":"347 U.S. 128","y":1954,"id":"1940-1955/347us128","sc":1,"sum":"The Court upheld Irvine's conviction though without commanding a majority as to the Court's reasoning.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"sum":"Petitioner Izumi Seimitsu Kogyo Kabushiki Kaisha was a party at the first trial in an action brought against it and respondent Windmere Corporation by respondent U. S. Philips Corporation, but was not a party to the second trial, in which Windmere prevailed. While the judgments from the second trial were on appeal, respondents reached a settlement and filed a joint motion to vacate the District Court's judgments. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Jacobs v. Tempur Pedic Int’l, Inc.","cite":"626 F.3d 1327","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/626/1327/","by":{"1":"30"}},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"op":1,"sum":"The saving clause in 28 U. S. C. §2255(e) does not allow a prisoner asserting an intervening change in the interpretation of a criminal statute to circumvent the Antiterrorism and Effective Death Penalty Act of 1996’s restrictions on second or successive §2255 motions by filing a habeas petition under §2241.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38","2":"22"}},{"t":"case","label":"Jones v. Hildebrant","cite":"432 U.S. 183","y":1977,"id":"1976/76-5416","sc":1,"sum":"Where petitioner's counsel informed this Court at oral argument that petitioner's sole claim of constitutional deprivation resulting from her minor son's being shot and killed by respondent police officer was one based on her personal liberty and not one of pecuniary loss such as would be covered by Colorado's wrongful-death statute, but that contention was neither alleged in her complaint (which included claims …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Laber v. Harvey","cite":"438 F.3d 404","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/438/404/","by":{"1":"23","2":"15"}},{"t":"case","label":"Lackawanna Cnty. Dist. Att’y v. Coss","cite":"532 U.S. 394","y":2001,"id":"2000/99-1884","sc":1,"sum":"The Court held that \"once a state conviction is no longer open to direct or collateral attack in its own right because the defendant failed to pursue those remedies while they were available (or because the defendant did so unsuccessfully), the conviction may be regarded as conclusively valid.","sumSrc":"Oyez","by":{"1":"12, 18"}},{"t":"case","label":"Leisure Caviar, LLC v. U.S. Fish & Wildlife Serv.","cite":"616 F.3d 612","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/616/612/","by":{"1":"23"}},{"t":"case","label":"Liljeberg v. Health Servs. Acquisition Corp.","cite":"486 U.S. 847","y":1988,"id":"1987/86-957","sc":1,"sum":"In 1977, pursuant to a plan to construct and operate a hospital in Kenner, Louisiana, petitioner formed a corporation (St. Jude) to apply for the necessary state \"certificate of need.\" During the next two years petitioner negotiated with Loyola University over a proposal to purchase as the hospital site a portion of Loyola's Kenner land for several million dollars, coupled with a plan to rezone Loyola's adjoining …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Martinez v. Ryan","cite":"926 F.3d 1215","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/926/1215/","by":{"1":"41"}},{"t":"case","label":"Maslenjak v. United States","cite":"582 U.S. 335","y":2017,"id":"2016/16-309","sc":1,"sum":"The Court determined that, for a naturalized American citizen to be stripped of her citizenship, the government has to prove that she obtained her citizenship illegally; if the underlying illegality is a false statement to government officials, the government must prove that the false statement influenced the citizenship process.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"McKay v. Novartis Pharm. Corp.","cite":"751 F.3d 694","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/751/694/","by":{"1":"33"}},{"t":"case","label":"Montiel v. Chappell","cite":"43 F.4th 942","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/43/942/","by":{"1":"42"}},{"t":"case","label":"Panetti v. Quarterman","cite":"551 U.S. 930","y":2007,"id":"2006/06-6407","sc":1,"sum":"The Court held that the Fifth Circuit's analysis was too restrictive under Ford v. Wainwright , because it treated Panetti's mental condition as irrelevant as long as he had in some sense a factual awareness of the state's rationale.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Pipefitters Loc. 636 Ins. Fund v. Blue Cross & Blue Shield of Mich.","cite":"418 F.App’x 430","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.App%E2%80%99x/418/430/","by":{"1":"43"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"1":"29","2":"14"}},{"t":"case","label":"Ramos v. Louisiana","cite":"590 U.S. 83","y":2020,"id":"2019/18-5924","sc":1,"op":8,"sum":"The Court held that the Fourteenth Amendment fully incorporates the Sixth Amendment’s guarantee of a unanimous verdict against the states.","sumSrc":"Oyez","by":{"1":"21","3":"2"}},{"t":"case","label":"Rhines v. Weber","cite":"544 U.S. 269","y":2005,"id":"2004/03-9046","sc":1,"sum":"The Court held that a district court could stay a mixed petition to allow a petitioner to present unexhausted claims in state court and then return to federal court.","sumSrc":"Oyez","by":{"1":"26","2":"22"}},{"t":"case","label":"Rivers v. State","cite":"2014 WL 3662569","y":2014,"court":"Tex. App.—El Paso, July 23","by":{"1":"6"}},{"t":"case","label":"Rose v. Lundy","cite":"455 U.S. 509","y":1982,"id":"1981/80-846","sc":1,"sum":"The judgment is reversed and the case is remanded. 624 F. 2d 1100, reversed and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, III-A, III-B, and IV, concluding that a district court must dismiss habeas petitions containing both unexhausted and exhausted claims. A rule requiring exhaustion of all claims in state courts promotes comity and furthers the purposes underlying …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Royal Bus. Grp., Inc. v. Realist, Inc.","cite":"933 F.2d 1056","y":1991,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/933/1056/","by":{"1":"43"}},{"t":"case","label":"Runnion ex rel. Runnion v. Girl Scouts of Greater Chi. & Nw. Ind.","cite":"786 F.3d 510","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/510/","by":{"1":"24"}},{"t":"case","label":"Ruotolo v. City of New York","cite":"514 F.3d 184","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/514/184/","by":{"1":"23"}},{"t":"case","label":"Shinn v. Ramirez","cite":"596 U.S. 366","y":2022,"id":"2021/20-1009","sc":1,"sum":"Under 28 U. S. C. §2254(e)(2), a federal habeas court may not conduct an evidentiary hearing or otherwise consider evidence beyond the state-court record based on the ineffective assistance of state postconviction counsel.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18, 38"}},{"t":"case","label":"(ctd.): Slack v. McDaniel","cite":"529 U.S. 473","y":2000,"id":"1999/98-6322","sc":1,"op":1,"sum":"The Court held that a federal habeas corpus petition filed by a state prisoner, after an initial petition was dismissed without adjudication on the merits, does not constitute a \"second or successive\" petition, subject to dismissal for abuse of writ.","sumSrc":"Oyez","by":{"1":"19, 40, 41","2":"22"}},{"t":"case","label":"Stanton v. Liaw","cite":"2023 WL 3645525","y":2023,"court":"7th Cir. May 25","by":{"1":"32","3":"14"}},{"t":"case","label":"Stewart v. Martinez-Villareal","cite":"523 U.S. 637","y":1998,"id":"1997/97-300","sc":1,"op":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court ruled Martinez-Villareal cannot be barred from raising his incompetency claim in a successive petition because his claim was really amended.","sumSrc":"Oyez","by":{"1":"40, 41","2":"22"}},{"t":"case","label":"Tool Box, Inc. v. Ogden City Corp.","cite":"419 F.3d 1084","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/419/1084/","by":{"1":"24","2":"14"}},{"t":"case","label":"United States v. Harrison","cite":"469 F.3d 1216","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/469/1216/","by":{"1":"24","2":"15"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Clinton","cite":"566 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"sum":"The Court held that a dispute over passport regulation was not a political issue and is thus liable for judicial review.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"1":"17"}},{"t":"case","label":"(III) Cases—Continued: Bannister v. Armontrout","cite":"807 F. Supp. 516","y":1991,"court":"W.D. Mo.","url":"https://www.courtlistener.com/c/F.%20Supp./807/516/","by":{"2":"25"}},{"t":"case","label":"Bonin v. Calderon","cite":"59 F.3d 815","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/59/815/","by":{"2":"26","3":"9"}},{"t":"case","label":"Bonin v. Vazquez","cite":"999 F.2d 425","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/999/425/","by":{"2":"26","3":"9"}},{"t":"case","label":"Building Indus. Ass’n v. Norton","cite":"247 F.3d 1241","y":2001,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/247/1241/","by":{"2":"15"}},{"t":"case","label":"Coinbase, Inc. v. Bielski","cite":"599 U.S. 736","y":2023,"id":"2022/22-105","sc":1,"op":1,"sum":"A district court must stay its proceedings while an interlocutory appeal taken pursuant to 9 U. S. C. §16(a) on the question of arbitrability is ongoing.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20"}},{"t":"case","label":"Cooper v. Shumway","cite":"780 F.2d 27","y":1985,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/780/27/","by":{"2":"15"}},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"sum":"The Court stated that the Eighth Circuit could not order the district court to increase Greenlaw's sentence without a request from the government to do so. The Court pointed to several of its precedents for the rule that a remedy in favor the appellee, in this case the government, can only be justified if the appellee brings a cross-appeal.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Hunt v. Nuth","cite":"57 F.3d 1327","y":1995,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/57/1327/","op":1,"by":{"2":"25","3":"16"}},{"t":"case","label":"Jimenez v. Quarterman","cite":"555 U.S. 113","y":2009,"id":"2008/07-6984","sc":1,"sum":"The Court held that if a state court grants a criminal defendant the right to file an out-of-time direct appeal, the statute of limitations doesn't begin until after the out-of-time appeal is final.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Johnson v. United States","cite":"196 F.3d 802","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/196/802/","by":{"2":"15"}},{"t":"case","label":"Lindauer v. Rogers","cite":"91 F.3d 1355","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/91/1355/","by":{"2":"15"}},{"t":"case","label":"MacPhee v. MiMedx Grp., Inc.","cite":"73 F.4th 1220","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/73/1220/","by":{"2":"15"}},{"t":"case","label":"Miller-El v. Cockrell","cite":"537 U.S. 322","y":2003,"id":"2002/01-7662","sc":1,"sum":"The Court held that the Court of Appeals should have issued a COA to review the District Court's denial of habeas corpus relief.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Morse v. McWhorter","cite":"290 F.3d 795","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/290/795/","by":{"2":"15"}},{"t":"case","label":"Ochoa v. Sirmons","cite":"485 F.3d 538","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/485/538/","op":1,"by":{"2":"23"}},{"t":"case","label":"Palmer v. Champion Mortg.","cite":"465 F.3d 24","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/465/24/","by":{"2":"14"}},{"t":"case","label":"Phillips v. United States","cite":"668 F.3d 433","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/668/433/","op":1,"by":{"2":"8, 13, 22, 23"}},{"t":"case","label":"Smith v. Armontrout","cite":"888 F.2d 530","y":1989,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/888/530/","by":{"2":"25","3":"9"}},{"t":"case","label":"Unitherm Food Sys., Inc. v. Swift-Eckrich, Inc.","cite":"546 U.S. 394","y":2006,"id":"2005/04-597","sc":1,"sum":"The Court ruled that a party must renew its motion for judgment under Rule 50(b) if the motion is to be the basis for an appeal.","sumSrc":"Oyez","by":{"2":"29","3":"12"}},{"t":"case","label":"Vesely v. Armslist LLC","cite":"762 F.3d 661","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/762/661/","by":{"2":"15"}},{"t":"case","label":"Vielma v. Eureka Co.","cite":"218 F.3d 458","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/218/458/","by":{"2":"15"}},{"t":"case","label":"Williams v. Citigroup Inc.","cite":"659 F.3d 208","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/659/208/","op":1,"by":{"2":"14"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"2":"23, 24"}},{"t":"case","label":"Arcadia v. Ohio Power Co.","cite":"498 U.S. 73","y":1990,"id":"1990/89-1283","sc":1,"sum":"Respondent Ohio Power Co. is subject to the overlapping regulatory jurisdiction of the Securities and Exchange Commission (SEC) under the Public Utility Holding Company Act (PUHCA) and the Federal Energy Regulatory Commission (FERC) under the Federal Power Act (FPA). In a series of orders authorizing Ohio Power to establish and capitalize an affiliate to secure and develop a reliable source of coal, the SEC …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Behringer v. Johnson","cite":"75 F.3d 189","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/75/189/","op":1,"by":{"3":"16"}},{"t":"case","label":"Beverley v. N.Y.C. Health & Hosp. Corp.","cite":"2020 WL 5750828","y":2020,"court":"S.D.N.Y. Sept. 25","by":{"3":"13"}},{"t":"case","label":"Carbiener v. Lender Processing Servs., Inc.","cite":"2014 WL 12616966","y":2014,"court":"M.D. Fla. Sept. 29","by":{"3":"12"}},{"t":"case","label":"Carriger v. Lewis","cite":"971 F.2d 329","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/971/329/","by":{"3":"16"}},{"t":"case","label":"Chafin v. Chafin","cite":"568 U.S. 165","y":2013,"id":"2012/11-1347","sc":1,"sum":"The Court decided that the return of a child to his or her country of residence pursuant to The Hague Convention, does not make an appeal of that order moot.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"City of Sherrill v. Oneida Indian Nation","cite":"544 U.S. 197","y":2005,"id":"2004/03-855","sc":1,"sum":"The Court held that standards of federal Indian law and federal equity precluded the Tribe from unilaterally reviving its ancient sovereignty over the land at issue.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Estelle v. Gamble","cite":"429 U.S. 97","y":1976,"id":"1976/75-929","sc":1,"sum":"The Court held that the prison’s treatment of Gamble did not constitute cruel and unusual punishment under the Eighth Amendment.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"First Nat’l Bank of La. v. Cont’l Ill. Nat’l Bank & Tr. Co.","cite":"933 F.2d 466","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/933/466/","op":2,"ar":3,"by":{"3":"14"}},{"t":"case","label":"Fogerty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"sum":"The Court held that while attorney's fees are awarded from time to time to prevailing defendants or plaintiffs, this practice is entirely subject to the deciding court's discretion. Indeed, the Court observed, that the statute in question emphasizes such discretion by stating in relevant part that a court \"may\" award attorney's fees.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"588 U.S. 427","y":2019,"id":"2018/18-481","sc":1,"op":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"2"}},{"t":"case","label":"Ford v. Armontrout","cite":"916 F.2d 457","y":1990,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/916/457/","by":{"3":"16"}},{"t":"case","label":"Gajewski v. Stevens","cite":"346 F.2d 1000","y":1965,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/346/1000/","by":{"3":"9"}},{"t":"case","label":"Giarratano v. Procunier","cite":"891 F.2d 483","y":1989,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/891/483/","op":1,"by":{"3":"16"}},{"t":"case","label":"Glossip v. Oklahoma","cite":"145 S. Ct. 612","y":2025,"id":"2024/22-7466","sc":1,"sum":"The Court has jurisdiction to review the judgment of the Oklahoma Court of Criminal Appeals; the prosecution violated its constitutional obligation to correct false testimony under Napue v. Illinois, 360 U. S. 264.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"2"}},{"t":"case","label":"Guinan v. Delo","cite":"5 F.3d 313","y":1993,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/5/313/","by":{"3":"16"}},{"t":"case","label":"Kamen v. Kemper Fin. Servs., Inc.","cite":"500 U.S. 90","y":1991,"id":"1990/90-516","sc":1,"sum":"A court entertaining a derivative action under the ICA must apply the demand futility exception as it is defined by the law of the State of incorporation.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Lawrence v. Chater","cite":"516 U.S. 163","y":1996,"id":"1995/94-9323","sc":1,"sum":"In a 7-2 per curiam opinion, the Court held that it had the power to issue a GVR order and that such an order is an appropriate exercise of its discretionary certiorari jurisdiction. \"In an appropriate case, a GVR order conserves the scarce resources of this Court that might otherwise be expended on plenary consideration, assists the court below by flagging a particular issue that it does not appear to have fully considered, assists this Court by procuring the benefit of the lower court's insight before we rule on the merits, and alleviates the 'potential for unequal treatment' that is inherent in our inability to grant plenary review of all pending cases raising similar issues,\" stated the unsigned opinion.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Lynaugh v. Petty","cite":"480 U.S. 699","y":1987,"id":"1986/85-1656","sc":1,"by":{"3":"16"}},{"t":"case","label":"May v. Collins","cite":"961 F.2d 74","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/961/74/","by":{"3":"16"}},{"t":"case","label":"McQueen v. Scroggy","cite":"99 F.3d 1302","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/99/1302/","by":{"3":"16"}},{"t":"case","label":"Moreland v. Robinson","cite":"813 F.3d 315","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/813/315/","by":{"3":"20"}},{"t":"case","label":"Morgan v. Sundance, Inc.","cite":"596 U.S. 411","y":2022,"id":"2021/21-328","sc":1,"sum":"Federal courts may not adopt an arbitration-specific rule conditioning a waiver of the right to arbitrate on a showing of prejudice.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"10"}},{"t":"case","label":"Nat’l Cable & Telecomms. Ass’n v. Gulf Power Co.","cite":"534 U.S. 327","y":2002,"id":"2001/00-832","sc":1,"sum":"The Court held 6-2 that the Act covers attachments that provide high-speed Internet access at the same time as cable television and 8-0 that the Act applies to wireless attachments by providers of wireless telecommunications services.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"Patterson v. Alabama","cite":"294 U.S. 600","y":1935,"id":"scdb/1934-165","sc":1,"sum":"1. Upon review of a judgment of a state court disposing of the case on a point of local practice without adjudicating a claim of federal right, this Court must examine the record and determine whether the non-federal ground is adequate to sustain the judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"14"}},{"t":"case","label":"Perez v. Sturgis Pub. Schs.","cite":"598 U.S. 142","y":2023,"id":"2022/21-887","sc":1,"sum":"An Americans with Disabilities Act lawsuit seeking compensatory damages for the denial of a free and appropriate education may proceed without exhausting the administrative processes of the Individuals with Disabilities Education Act, 20 U. S. C. §1415(l), because the remedy sought is not one IDEA provides.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"15"}},{"t":"case","label":"PETA v. HHS","cite":"901 F.3d 343","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/901/343/","by":{"3":"13"}},{"t":"case","label":"Resnover v. Pearson","cite":"1993 WL 430159","y":1993,"court":"7th Cir. Oct. 22","by":{"3":"16"}},{"t":"case","label":"Scriber v. Ford Motor Co.","cite":"2024 WL 2830499","y":2024,"court":"S.D. Cal. June 4","by":{"3":"12"}},{"t":"case","label":"Sherrod v. Am. Airlines, Inc.","cite":"132 F.3d 1112","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/132/1112/","by":{"3":"3"}},{"t":"case","label":"U.S. Bancorp Mortg. Co. v. Bonner Mall P’hip","cite":"513 U.S. 18","y":1994,"id":"1994/93-714","sc":1,"sum":"After this Court granted the petition for a writ of certiorari and received briefing on the merits, the parties entered into a settlement and agreed that the case was thereby mooted. Petitioner, however, also requested that the Court exercise its power under 28 U. S. C. § 2106 to vacate the judgment of the Court of Appeals. Respondent opposed the motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"11, 12"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"sum":"The Court held that the Court of Appeals erred in concluding that this was a sufficient basis to justify reopening the judgment. \"[A]n independent action should be available only to prevent a grave miscarriage of justice,\" wrote Chief Justice Rehnquist, \"it should be obvious that [the Beggerlys'] allegations do not nearly approach this demanding standard.\" The Court also concluded that the Court of Appeals extension of the Quiet Title Act's statutory period by equitable tolling was unwarranted, given its generous nature.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"United States v. Edmonson","cite":"928 F. Supp. 1052","y":1996,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp./928/1052/","by":{"3":"16"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"rule","label":"Fed. R. App. P. 4","url":"https://www.law.cornell.edu/rules/frap/rule_4","subs":["(a)(1)(B)"],"by":{"3":"20"}},{"t":"rule","label":"Fed. R. Civ. P. 7","url":"https://www.law.cornell.edu/rules/frcp/rule_7","subs":["(b)(1)(C)"],"by":{"3":"12"}}]};